import Base

type Box<-A: Type> is Type:
  Box{value: A}

type Request is Type:
  Number{value: U32}
  Owned{items: Array<U32>}

def result_type(request: Request) -> Type:
  match request:
    case Number{_}: U32
    case Owned{_}: Array<U32>

type Progress<-A: Type> is Type:
  Finished{box: Box<A>}
  Pending{request: Request, resume: (@box: Box<result_type(request)> -> Progress<A>)}
  Direct{-R: Type, -request: Request, arguments: R, invoke: (@arguments: R -> Progress<result_type(request)>), resume: (@box: Box<result_type(request)> -> Progress<A>)}
  Bound{-B: Type, inner: Progress<B>, resume: (@box: Box<B> -> Progress<A>)}

def dispatch(request: Request) -> Progress<result_type(request)>:
  match request:
    case Number{value}: Finished{Box{value}}
    case Owned{items}: Finished{Box{items}}

# A scheduling quantum yields its remaining computation, never an error.
# The bound is operational, unrelated to the checker's WHNF semantic fuel.
def chunk(-A: Type, fuel: Nat, progress: Progress<A>) -> Progress<A>:
  match fuel progress:
    case 0n state: state
    case 1n+rest Finished{box}: Finished{box}
    case 1n+rest Pending{request, resume}:
      chunk(A, rest, Bound{result_type(request), dispatch(request), resume})
    case 1n+rest Direct{R, request, arguments, invoke, resume}:
      chunk(A, rest, Bound{result_type(request), invoke(arguments), resume})
    case 1n+rest Bound{B, inner, resume}:
      match inner:
        case Finished{box}: chunk(A, rest, resume(box))
        case Pending{request, next}:
          chunk(A, rest, Pending{request, box => Bound{B, next(box), resume}})
        case Direct{R, request, arguments, invoke, next}:
          chunk(A, rest, Direct{R, request, arguments, invoke, box => Bound{B, next(box), resume}})
        case Bound{C, nested, next}:
          chunk(A, rest, Bound{C, nested, box => Bound{B, next(box), resume}})

def twice(box: Box<U32>) -> Progress<U32>:
  match box:
    case Box{+value}: Finished{Box{U32.add(value, value)}}

def keep_data(box: Box<U32>) -> Progress<U32>:
  Finished{box}

def owned_result(items: Array<U32>) -> Progress<Array<U32>>:
  Finished{Box{items}}

def keep_owned(box: Box<Array<U32>>) -> Progress<Array<U32>>:
  match box:
    case Box{items}: Finished{Box{items}}

def read_result(result: Array<U32> & U32) -> Progress<U32>:
  match result:
    case Tuple{_, value}: Finished{Box{value}}

def read_owned(box: Box<Array<U32>>) -> Progress<U32>:
  match box:
    case Box{items}: read_result(Array.get(U32, items, 0))

def data_program() -> Progress<U32>:
  Pending{Number{21}, twice}

def owned_program(items: Array<U32>) -> Progress<U32>:
  Bound{U32, Bound{Array<U32>, Pending{Owned{items}, keep_owned}, read_owned}, twice}

def direct_program(items: Array<U32>) -> Progress<U32>:
  Bound{U32, Direct{Array<U32>, Owned{items}, items, owned_result, read_owned}, twice}

def allocate() -> Array<U32>:
  Array.set(U32, Array.new(U32, 0n, 0), 0, 21)

type NativeView<-A: Type> is Type:
  NativeFinished{box: Box<A>}
  NativeMore{-B: Type, next: Unit -> Progress<B>, resume: (@box: Box<B> -> Progress<A>)}

def native_view_ready(-A: Type, progress: Progress<A>) -> NativeView<A>:
  match progress:
    case Finished{box}: NativeFinished{box}
    case Pending{request, resume}: NativeMore{result_type(request), unit => dispatch(request), resume}
    case Direct{R, request, arguments, invoke, resume}: NativeMore{result_type(request), unit => invoke(arguments), resume}
    case Bound{B, inner, resume}: NativeMore{B, unit => inner, resume}

def native_view(-A: Type, quantum: Nat, progress: Progress<A>) -> NativeView<A>:
  native_view_ready(A, chunk(A, quantum, progress))

def native_view64(-A: Type, progress: Progress<A>) -> NativeView<A>:
  native_view_ready(A, chunk(A, 64n, progress))

def plus_three(box: Box<U32>) -> Progress<U32>:
  match box:
    case Box{value}: Finished{Box{U32.add(value, 3)}}

def ordered_program() -> Progress<U32>:
  Bound{U32, Bound{U32, Finished{Box{7}}, twice}, plus_three}

def reversed_program() -> Progress<U32>:
  Bound{U32, Bound{U32, Finished{Box{7}}, plus_three}, twice}

def ordered_owned(items: Array<U32>) -> Progress<U32>:
  Bound{U32, Bound{U32, Bound{Array<U32>, Pending{Owned{items}, keep_owned}, read_owned}, twice}, plus_three}

