import {createHash} from 'node:crypto';
import {readFileSync,writeFileSync} from 'node:fs';
import {resolve} from 'node:path';
const root=resolve(import.meta.dir,'..'),prefix=resolve(import.meta.dir,'.native-boundary55-model');
const hash=(p:string)=>createHash('sha256').update(readFileSync(p)).digest('hex');
const report:any={status:'RUNNING',scope:'Small typed boundary model, not full compiler acceptance, C ABI execution, or speed evidence',sourceSha256:hash(prefix+'.bend'),driverSha256:hash(import.meta.path),kernelSha256:hash(root+'/bend2/bend.ts'),compilerSha256:hash(root+'/bend2/comp.ts'),patches:0,unsafe:false,rows:[],firstFailures:[]};
let K:any,phase='pin';
try {
 if(report.kernelSha256!=='6c1df3eb304fe085070aa4797928f70243b80d4635389e3d5d8a49fdfbb3051e'||report.compilerSha256!=='8c33864a67f0fd08d1805929c8f48806c040b219126b29bb31f201f45d6b69e6')throw Error('Official source pin mismatch');
 K=await import(root+'/bend2/bend.ts');const C=await import(root+'/bend2/comp.ts');
 // Proof seam intentionally loads the official modules only after authenticating their bytes.
 phase='load';const book=K.book_nil();await K.book_load(book,prefix+'.bend','',new Map());
 phase='valid';K.book_valid(book);report.holes=book.hols;report.checkedBodies=Object.entries(book.tlds).filter(([,d]:any)=>d.$==='Def'&&d.v!==null).map(([name,d]:any)=>({name,checked:d.e!==undefined}));
 if(book.hols||report.checkedBodies.some((r:any)=>!r.checked))throw Error('Unchecked body or holes');
 phase='emit';writeFileSync(prefix+'.mjs',C.js_lib(book,true,{exports:['chunk','dispatch','data_program','owned_program','direct_program','allocate','keep_data','native_view_ready','native_view','native_view64','ordered_program','reversed_program','ordered_owned','twice','plus_three']}),{flag:'wx'});report.emittedSha256=hash(prefix+'.mjs');
 phase='execute';const api=(await import(prefix+'.mjs')).default;
 function run(name:string,make:()=>any,mode:string,quantum:number,expected:number){
  let state=make(),stack:any[]=[],turns=0,resumes=0,maxHostContinuationDepth=0;const start=performance.now();
  for(;;){
   turns++;
   if(mode==='original'){
    switch(state.$){
     case'Finished':if(stack.length){state=stack.pop()(state.box);resumes++;}else return finish(state.box);break;
     case'Pending':stack.push(state.resume);state=api.dispatch(state.request);break;
     case'Direct':stack.push(state.resume);state=state.invoke(state.arguments);break;
     case'Bound':stack.push(state.resume);state=state.inner;break;
     default:throw Error('Unknown original progress');
    }
   }else{
    const view=mode==='fixed64'?api.native_view64(state):mode==='ready'?api.native_view_ready(state):api.native_view(quantum,state);
    switch(view.$){
     case'NativeFinished':if(stack.length){state=stack.pop()(view.box);resumes++;}else return finish(view.box);break;
     case'NativeMore':stack.push(view.resume);state=view.next({$:'Unit'});break;
     default:throw Error('Unknown view '+view.$);
    }
   }
   maxHostContinuationDepth=Math.max(maxHostContinuationDepth,stack.length);
  }
  function finish(box:any){if(box.$!=='Box'||box.value!==expected)throw Error(`${name}/${mode}/${quantum}: expected ${expected}, got ${JSON.stringify(box)}`);const row={name,mode,quantum,expected,observed:box.value,hostReflections:turns,hostResumes:resumes,maxHostContinuationDepth,elapsedMs:performance.now()-start};report.rows.push(row);return row;}
 }
 const cases=[['data',()=>api.data_program(),42],['affine-array',()=>api.owned_program(api.allocate()),42],['direct-affine',()=>api.direct_program(api.allocate()),42],['multiply-then-add',()=>api.ordered_program(),17],['add-then-multiply',()=>api.reversed_program(),20],['affine-multiply-then-add',()=>api.ordered_owned(api.allocate()),45],['deep100000-noncommuting',()=>{let p=api.ordered_program();for(let n=0;n<100000;n++)p={$:'Bound',inner:p,resume:api.keep_data};return p;},17]] as const;
 for(const [name,make,expected]of cases){run(name,make,'original',0,expected);run(name,make,'ready',0,expected);for(const q of[0,1,64])run(name,make,'boundary',q,expected);run(name,make,'fixed64',64,expected);}
 report.status='PASS';
}catch(error){report.status='FAIL';report.firstFailures.push({phase,diagnostic:K&&error&&typeof error==='object'&&'$'in error&&error.$==='Err'?K.err_show(error):String(error)});}
report.sources={bend:readFileSync(prefix+'.bend','utf8'),driver:readFileSync(import.meta.path,'utf8')};
writeFileSync(prefix+'.json',JSON.stringify(report,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({status:report.status,phase,bodyCount:report.checkedBodies?.length,holes:report.holes,rows:report.rows,firstFailures:report.firstFailures,receipt:prefix+'.json'}));if(report.status!=='PASS')process.exitCode=1;

